404	    },
405	  };
406	};
407	
408	const registryReturning = (response: ToolResponse): ToolRegistry => {
409	  const registry = new ToolRegistry();
410	  registry.register(
411	    {name: 'lookup', description: 'looks things up', inputSchema: {type: 'object'}},
412	    async () => response
413	  );
