417	const TOOL_CALL: MessageChunk = {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {q: 'x'}}};
418	const STOP_FOR_TOOL: MessageChunk = {type: 'stop', stopReason: 'tool_use'};
419	const STOP_DONE: MessageChunk = {type: 'stop', stopReason: 'end_turn'};
